#!/usr/bin/env bash
# `.scratch/` follows docs/agents/issue-tracker.md: one directory per feature,
# a spec (or a wayfinder map), and issues/NN-slug.md files that carry Status:.
#
# Generated by omp (DeepSeek V4.1 Flash) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later
#
# The convention is only written down; nothing enforced it, and one run left a
# finished feature with no spec.md at all. `.scratch/` is gitignored, so this
# step skips in CI and guards a working checkout.
#
# Exit codes: 0 the tracker follows the convention, 1 it does not, 125 not
# applicable (no git checkout or no .scratch).
set -u

ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  tracker layout (not inside a git checkout)\n'
    exit 125
}
cd "$ROOT" || exit 1

if [ ! -d .scratch ]; then
    printf 'SKIP  tracker layout (no .scratch in this checkout)\n'
    exit 125
fi

shopt -s nullglob

bad=0
features=0
for dir in .scratch/*/; do
    feature=${dir%/}
    if [ -f "$feature/ARCHIVE.md" ]; then
        continue
    fi
    features=$((features + 1))
    if [ ! -f "$feature/spec.md" ] && [ ! -f "$feature/map.md" ]; then
        printf 'missing spec: %s/spec.md (or map.md for a wayfinder effort)\n' "$feature"
        bad=1
    fi
    for issue in "$feature"/issues/*.md; do
        name=$(basename "$issue")
        if ! printf '%s' "$name" | grep -Eq '^[0-9]{2}-[a-z0-9][a-z0-9-]*\.md$'; then
            printf 'issue name must be NN-slug.md: %s\n' "$issue"
            bad=1
        fi
        if ! head -n 20 "$issue" | grep -Eq '^Status:[[:space:]]*[a-z]+'; then
            printf 'missing Status: line near the top of %s\n' "$issue"
            bad=1
        fi
    done
done

printf 'checked %d feature director%s\n' "$features" "$([ "$features" -eq 1 ] && printf y || printf ies)"
[ "$bad" -eq 0 ]
